-- システム施設設定
delete from sys_facility_setting where facility_setting_no = '1001';
delete from sys_facility_setting where facility_setting_no = '1002';
delete from sys_facility_setting where facility_setting_no = '1003';
delete from sys_facility_setting where facility_setting_no = '1004';

insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date)  values ('1001', '次患者更新モード', '3', 4, '[{"id":"1", "name":"1:次クールの治療予定"},{"id":"2", "name":"2:指定期間直近治療予定"},{"id":"3","name":"3:翌日まで直近の治療予定"}]', '患者更新モード', 0, '次患者更新のモードを設定します。<br>　1：次クールに治療予定がある患者を次患者とします。<br>　　ただし、現在時刻が当日の最後のクールの場合は翌日（翌日が休日（日曜）の場合は次の営業日）の最初のクールに治療予定がある患者を次患者とします。<br>　　また、休日（日曜）に治療予定がある場合は次クールでない場合でも次患者とします。（休日（日曜）のみモード２扱いとなります。））<br>　2：休日（日曜）も含め、指定期間内（当日＋次患者検索日数）の直近に治療予定がある患者を次患者とします。<br>　3：翌日（翌日が休日（日曜）の場合は次の営業日）までの直近に治療予定がある患者を次患者とします。', 1, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date)  values ('1002', '次患者検索日数', '1', 2, '[{"max":"100", "min":"0"}]', '患者検索日数', 0, '翌日以降の検索日数を設定します。<br>　※次患者更新モードで「2」を設定時のみ有効となります。', 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date)  values ('1003', 'サインインタイムアウト時間設定 （分）', '60', 2, '[{"max":"999", "min":"0"}]', 'タイムアウト時間設定', 0, '施設毎のサインインタイムアウト時間設定。<br> 設定時間サーバとの通信がなかった場合、時間経過後サーバとの通信の時点でサインアウト画面へ遷移します。', 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date)  values ('1004', '透析困難リセット機能', '0', 3, '', '透析困難リセット', 0, '透析困難リセット機能の使用設定。（0：OFF、1：ON）<br>　「1：ON」に設定した場合、患者情報画面で入外区分を入院から外来に切り替えて登録する際に、透析困難情報をリセットします。リセットを行う際は処理前に確認メッセージが表示され、リセットを行うか否か選択することが出来ます。', 4, current_timestamp, current_timestamp );
